/* ================================================================
 * 正在播放 —— 把酒馆排成一个音乐播放器：角色是歌手，聊天是一张专辑
 *
 * 作者：mangosagocreamwithpomelo（Discord）
 * 设计与实现：Claude Opus 5.5（Anthropic）
 * 借的是流媒体播放器的思路（颜色从封面来、底部播放条、正在播放侧栏），
 * 不含任何播放器的商标、图标或字体。
 *
 * 颜色跟着角色走：主题伴侣扩展读当前角色的头像，取一个主色写进 --np-art。
 * 不装扩展时用 --np-art-default（一块中性灰）。
 * ================================================================ */

@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;700;800;900&family=Noto+Sans+SC:wght@400;500;700;900&display=swap');

/* ================================================================
 * 可改区：想调整的都在这里，改完点空白处即可生效。改坏了重新导入主题就能恢复。
 * 文字、面板的颜色在酒馆「用户设置 → 主题颜色」里改。
 * ================================================================ */
html:root {
    /* —— 颜色 —— */
    --np-accent: #2ee26b;          /* 强调色：正在播放的名字、音柱、打开的图标下面的小点 */
    --np-on-accent: #000;          /* 强调色上的字 */
    --np-base: #000;               /* 面板之间的底色 */
    --np-art-default: #535353;     /* 没装扩展、或头像取不到颜色时的封面色 */

    /* —— 字体 —— */
    --np-font: 'Figtree', 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    --np-prose-size: 16px;         /* 正文字号 */
    --np-prose-leading: 1.75;      /* 正文行距 */

    /* —— 电脑版面 —— */
    --np-side: 340px;              /* 左栏（资料库）和右栏（正在播放）的宽度 */
    --np-gap: 8px;                 /* 面板之间的缝 */
    --np-pad: 28px;                /* 正文离聊天面板左右边的距离 */

    /* —— 手机版面 —— */
    --np-m-pad: 14px;              /* 正文离屏幕左右边的距离 */
}

/* ==== themes/nowplaying/base.css ==== */
/* ================================================================
 * 正在播放 · 母版
 * 版面（电脑）：
 *   中间 #sheld     聊天 = 一张专辑：顶上封面 + 大名字（#np_hero），消息像曲目一样带序号
 *   底部 #form_sheld 播放条：左边正在播放的角色，中间输入框，右边 上一版 / 发送 / 下一版
 *   左右用酒馆自己的面板：左 = AI 设置（预设），右 = 角色（列表是资料库，打开一个角色是「正在播放」）
 * 手机：顶栏挪到底部当标签栏，播放条是浮在标签栏上面、带封面色的一小块。
 * ================================================================ */

@property --np-art {
    syntax: '<color>';
    inherits: true;
    initial-value: #535353;
}

@property --np-b1 { syntax: '<percentage>'; inherits: false; initial-value: 40%; }
@property --np-b2 { syntax: '<percentage>'; inherits: false; initial-value: 80%; }
@property --np-b3 { syntax: '<percentage>'; inherits: false; initial-value: 55%; }

:root {
    --np-art: var(--np-art-default);
    --np-on-art: #fff;
    --np-panel: var(--SmartThemeBlurTintColor);
    --np-text: var(--SmartThemeBodyColor);
    --np-sub: var(--SmartThemeEmColor);
    --np-line: var(--SmartThemeBorderColor);
    --np-hover: color-mix(in srgb, var(--SmartThemeBodyColor) 7%, transparent);
    --np-elev: color-mix(in srgb, var(--SmartThemeBodyColor) 9%, var(--SmartThemeBlurTintColor));
    --np-elev-hi: color-mix(in srgb, var(--SmartThemeBodyColor) 15%, var(--SmartThemeBlurTintColor));
    --np-bar: 84px;                 /* 播放条高度，主题脚本按实际高度改 */
    --mainFontFamily: var(--np-font);
    --np-ease: cubic-bezier(.3, 0, 0, 1);
}

/* 换角色时封面色慢慢过渡过去 */
html {
    transition: --np-art 900ms ease;
}

body {
    background: var(--np-base);
    font-family: var(--np-font);
}

#bg1,
#bg_custom {
    opacity: 0 !important;
}

* {
    text-shadow: none !important;
}

/* ==== themes/nowplaying/icons.css ==== */
/* ================================================================
 * 图标：照播放器的画法重画（24 格、2 像素圆头线条；平时是线，打开时是实心）
 * 每个图标两张：--np-i-<名> 线条版，--np-i-<名>-on 实心版。用 mask 画，颜色跟着文字色走
 * ================================================================ */
:root {
    /* 预设（AI 设置）：两根推子 */
    --np-i-presets: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M3.5 7h8.5M18 7h2.5M3.5 17h2.5M12 17h8.5'/><circle cx='15' cy='7' r='2.5'/><circle cx='9' cy='17' r='2.5'/></svg>");
    --np-i-presets-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M3.5 7h8.5M18 7h2.5M3.5 17h2.5M12 17h8.5'/><circle cx='15' cy='7' r='3'/><circle cx='9' cy='17' r='3'/></svg>");
    /* API 连接：插头 */
    --np-i-api: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M9 3v4M15 3v4M6.5 7h11v3.5a5.5 5.5 0 0 1-11 0zM12 16v5'/></svg>");
    --np-i-api-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M9 3v4M15 3v4M12 16v5'/><path fill='black' d='M6.5 7h11v3.5a5.5 5.5 0 0 1-11 0z'/></svg>");
    /* 高级格式：Aa */
    --np-i-format: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M2.5 19 7.5 5l5 14M4.5 14h6'/><circle cx='17.5' cy='15.5' r='3'/><path d='M20.5 12v7'/></svg>");
    --np-i-format-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'><path d='M2.5 19 7.5 5l5 14M4.5 14h6'/><circle cx='17.5' cy='15.5' r='3'/><path d='M20.5 12v7'/></svg>");
    /* 世界书：一本书 */
    --np-i-book: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M5 18.5V5a2 2 0 0 1 2-2h12v15H6.5a1.5 1.5 0 0 0 0 3H19'/><path d='M9 7.5h6'/></svg>");
    --np-i-book-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path fill='black' fill-rule='evenodd' d='M5 18.5V5a2 2 0 0 1 2-2h12v15H6.5A1.5 1.5 0 0 0 5 18.5zM9 6.5a1 1 0 0 0 0 2h6a1 1 0 0 0 0-2z'/><path d='M5 18.5a1.5 1.5 0 0 0 1.5 1.5H19'/></svg>");
    /* 用户设置：齿轮 */
    --np-i-gear: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black'><circle cx='12' cy='12' r='8.3' stroke-width='3.4' stroke-dasharray='3.26 3.26'/><circle cx='12' cy='12' r='6' stroke-width='2'/><circle cx='12' cy='12' r='2.2' stroke-width='2'/></svg>");
    --np-i-gear-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black'><circle cx='12' cy='12' r='8.3' stroke-width='3.4' stroke-dasharray='3.26 3.26'/><circle cx='12' cy='12' r='4.6' stroke-width='4.8'/></svg>");
    /* 背景：一幅画 */
    --np-i-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='5' width='18' height='14' rx='2'/><path d='m3.5 17 5-5 3.5 3.5 2.5-2.5 6 5'/><circle cx='16' cy='9.5' r='1.3' fill='black'/></svg>");
    --np-i-image-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='black' fill-rule='evenodd' d='M5 4h14a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3H5a3 3 0 0 1-3-3V7a3 3 0 0 1 3-3zm-.5 13.5h15L14.5 13 12 15.5 8.5 12zM16 8a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3z'/></svg>");
    /* 扩展：三块方 + 一块斜放 */
    --np-i-ext: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'><rect x='3.5' y='3.5' width='7' height='7' rx='1.5'/><rect x='3.5' y='13.5' width='7' height='7' rx='1.5'/><rect x='13.5' y='13.5' width='7' height='7' rx='1.5'/><rect x='14' y='3' width='6' height='6' rx='1.5' transform='rotate(45 17 6)'/></svg>");
    --np-i-ext-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black' stroke='black' stroke-width='2' stroke-linejoin='round'><rect x='3.5' y='3.5' width='7' height='7' rx='1.5'/><rect x='3.5' y='13.5' width='7' height='7' rx='1.5'/><rect x='13.5' y='13.5' width='7' height='7' rx='1.5'/><rect x='14' y='3' width='6' height='6' rx='1.5' transform='rotate(45 17 6)'/></svg>");
    /* 人设：头和肩 */
    --np-i-persona: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><circle cx='12' cy='8' r='4.5'/><path d='M3.5 21a8.5 8.5 0 0 1 17 0'/></svg>");
    --np-i-persona-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black' stroke='black' stroke-width='2' stroke-linejoin='round'><circle cx='12' cy='8' r='4.5'/><path d='M3.5 21a8.5 8.5 0 0 1 17 0z'/></svg>");
    /* 角色（资料库）：两本竖着的书 + 一本斜靠 */
    --np-i-library: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M4.5 3v18M9.5 3v18M14 4.5l6 16'/></svg>");
    --np-i-library-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black'><rect x='3' y='2.5' width='3.4' height='19' rx='1'/><rect x='8' y='2.5' width='3.4' height='19' rx='1'/><path d='M12.6 4.6a1 1 0 0 1 .6-1.3l1.3-.5a1 1 0 0 1 1.3.6l5.6 15.4a1 1 0 0 1-.6 1.3l-1.3.5a1 1 0 0 1-1.3-.6z'/></svg>");
    /* 输入区：菜单（三点）、扩展菜单（星光） */
    --np-i-more: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black'><circle cx='5' cy='12' r='1.8'/><circle cx='12' cy='12' r='1.8'/><circle cx='19' cy='12' r='1.8'/></svg>");
    --np-i-spark: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'><path d='M10 3.5 11.8 8.2 16.5 10l-4.7 1.8L10 16.5l-1.8-4.7L3.5 10l4.7-1.8z'/><path d='m18 14 .9 2.1 2.1.9-2.1.9L18 20l-.9-2.1-2.1-.9 2.1-.9z'/></svg>");
}

/* 顶栏图标：酒馆的字体图标不画，换成上面的 */
#top-settings-holder .drawer-icon {
    font-size: 0 !important;
    width: 24px;
    height: 24px;
    padding: 0;
}

#top-settings-holder .drawer-icon::before {
    content: '' !important;
    display: block;
    width: 24px;
    height: 24px;
    background: currentColor;
    -webkit-mask: var(--np-ico) center / contain no-repeat;
    mask: var(--np-ico) center / contain no-repeat;
}

#ai-config-button .drawer-icon { --np-ico: var(--np-i-presets); }
#ai-config-button .drawer-icon.openIcon { --np-ico: var(--np-i-presets-on); }
#sys-settings-button .drawer-icon { --np-ico: var(--np-i-api); }
#sys-settings-button .drawer-icon.openIcon { --np-ico: var(--np-i-api-on); }
#advanced-formatting-button .drawer-icon { --np-ico: var(--np-i-format); }
#advanced-formatting-button .drawer-icon.openIcon { --np-ico: var(--np-i-format-on); }
#WI-SP-button .drawer-icon { --np-ico: var(--np-i-book); }
#WI-SP-button .drawer-icon.openIcon { --np-ico: var(--np-i-book-on); }
#user-settings-button .drawer-icon { --np-ico: var(--np-i-gear); }
#user-settings-button .drawer-icon.openIcon { --np-ico: var(--np-i-gear-on); }
#backgrounds-button .drawer-icon { --np-ico: var(--np-i-image); }
#backgrounds-button .drawer-icon.openIcon { --np-ico: var(--np-i-image-on); }
#extensions-settings-button .drawer-icon { --np-ico: var(--np-i-ext); }
#extensions-settings-button .drawer-icon.openIcon { --np-ico: var(--np-i-ext-on); }
#persona-management-button .drawer-icon { --np-ico: var(--np-i-persona); }
#persona-management-button .drawer-icon.openIcon { --np-ico: var(--np-i-persona-on); }
#rightNavHolder .drawer-icon { --np-ico: var(--np-i-library); }
#rightNavHolder .drawer-icon.openIcon { --np-ico: var(--np-i-library-on); }

/* 别的扩展加的顶栏按钮：保留它自己的字体图标，只统一大小和颜色 */
#top-settings-holder > .drawer:not(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon {
    font-size: 20px !important;
    width: auto;
    display: grid;
    place-items: center;
}

#top-settings-holder > .drawer:not(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon::before {
    content: revert !important;
    background: none;
    -webkit-mask: none;
    mask: none;
    width: auto;
    height: auto;
}

/* 输入区左边两个按钮 */
#options_button,
#extensionsMenuButton {
    font-size: 0 !important;
    width: 24px;
    height: 24px;
    display: grid;
    place-items: center;
}

#options_button::before,
#extensionsMenuButton::before {
    content: '' !important;
    width: 22px;
    height: 22px;
    background: currentColor;
    -webkit-mask: var(--np-ico) center / contain no-repeat;
    mask: var(--np-ico) center / contain no-repeat;
}

#options_button { --np-ico: var(--np-i-more); }
#extensionsMenuButton { --np-ico: var(--np-i-spark); }
/* ==== end themes/nowplaying/icons.css ==== */

/* ---------------- 顶栏 ---------------- */
#top-bar {
    background: var(--np-base);
    box-shadow: none;
    backdrop-filter: none;
}

#top-settings-holder .drawer-icon {
    color: var(--np-sub);
    opacity: 1;
    position: relative;
    transition: color .2s, transform .15s var(--np-ease);
}

#top-settings-holder .drawer-icon:hover {
    color: var(--np-text);
}

#top-settings-holder .drawer-icon:active {
    transform: scale(.92);
}

#top-settings-holder .drawer-icon.openIcon {
    color: var(--np-text);
}

/* 打开的那个图标下面一个小点（播放器里「正在用」的记号） */
#top-settings-holder .drawer-icon::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -7px;
    width: 4px;
    height: 4px;
    margin-left: -2px;
    border-radius: 50%;
    background: var(--np-accent);
    transform: scale(0);
    transition: transform .25s var(--np-ease);
}

#top-settings-holder .drawer-icon.openIcon::after {
    transform: scale(1);
}

/* ---------------- 聊天面板 ---------------- */
#sheld {
    background: var(--np-panel);
    border-radius: 8px;
    overflow: hidden;
}

#chat {
    background:
        linear-gradient(to bottom,
            var(--np-art) 0,
            color-mix(in srgb, var(--np-art) 45%, var(--np-panel)) 300px,
            var(--np-panel) 560px) var(--np-panel);
    background-attachment: local;
    padding: 0 var(--np-pad) 32px;
    gap: 2px;
}

/* 专辑头：封面 + 「角色」+ 大名字 + 一行小字 */
#np_hero {
    display: flex;
    align-items: flex-end;
    gap: 24px;
    padding: 64px 0 24px;
    color: var(--np-on-art);
    flex-shrink: 0;
    align-self: stretch;
}

#np_hero .np-cover {
    width: clamp(140px, 14vw, 220px);
    aspect-ratio: 1;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 4px;
    box-shadow: 0 8px 40px rgba(0, 0, 0, .5);
    flex-shrink: 0;
    background: var(--np-elev);
}

#np_hero .np-info {
    min-width: 0;
}

#np_hero .np-kicker {
    font-size: 14px;
    font-weight: 500;
}

#np_hero .np-title {
    font-size: clamp(40px, 5vw, 92px);
    font-weight: 900;
    line-height: 1.02;
    letter-spacing: -.03em;
    margin: 4px 0 14px;
    overflow-wrap: anywhere;
}

#np_hero .np-meta {
    font-size: 14px;
    opacity: .82;
}

#np_hero .np-meta b {
    font-weight: 700;
    opacity: 1;
}

/* 专辑头下面那排：大圆按钮 = 继续写 */
#np_actions {
    display: flex;
    align-items: center;
    gap: 24px;
    padding: 8px 0 24px;
    flex-shrink: 0;
}

.np-play {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: var(--np-accent);
    color: var(--np-on-accent);
    font-size: 22px;
    cursor: pointer;
    transition: transform .15s var(--np-ease), filter .15s;
}

.np-play:hover {
    transform: scale(1.05);
    filter: brightness(1.08);
}

.np-play:active {
    transform: scale(.95);
}

.np-play i {
    margin-left: 3px;
}

#np_actions .np-hint {
    color: var(--np-sub);
    font-size: 14px;
}

/* 往下滚以后，顶上一条细栏：封面色 + 小播放钮 + 名字 */
#np_top {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 64px;
    z-index: 35;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 var(--np-pad);
    background: color-mix(in srgb, var(--np-art) 70%, #000);
    color: var(--np-on-art);
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -.01em;
    opacity: 0;
    pointer-events: none;
    transition: opacity .25s;
}

#np_top .np-play {
    width: 40px;
    height: 40px;
    font-size: 15px;
}

html.np-scrolled #np_top {
    opacity: 1;
    pointer-events: auto;
}

/* ---------------- 消息 = 曲目 ---------------- */
#chat .mes {
    position: relative;
    padding: 12px 14px 14px 56px;
    border-radius: 6px;
    background: none;
    transition: background-color .2s;
}

#chat .mes:hover {
    background: var(--np-hover);
}

/* 序号（消息编号）；最新的回复是「正在播放」，序号变成强调色 */
#chat .mes::before {
    content: attr(mesid);
    position: absolute;
    left: 6px;
    top: 26px;
    width: 32px;
    text-align: right;
    font: 500 14px/1 var(--np-font);
    font-variant-numeric: tabular-nums;
    color: var(--np-sub);
}

#chat .mes.last_mes[is_user="false"]::before {
    color: var(--np-accent);
}

/* 生成中：序号换成三根跳动的音柱 */
@keyframes np-b1 { 0%, 100% { --np-b1: 25%; } 50% { --np-b1: 100%; } }
@keyframes np-b2 { 0%, 100% { --np-b2: 90%; } 50% { --np-b2: 30%; } }
@keyframes np-b3 { 0%, 100% { --np-b3: 45%; } 50% { --np-b3: 95%; } }

body[data-generating="true"] #chat .mes.last_mes[is_user="false"]::before {
    content: '';
    left: 24px;
    top: 24px;
    width: 14px;
    height: 14px;
    background:
        linear-gradient(var(--np-accent), var(--np-accent)) 0 100% / 3px var(--np-b1) no-repeat,
        linear-gradient(var(--np-accent), var(--np-accent)) 50% 100% / 3px var(--np-b2) no-repeat,
        linear-gradient(var(--np-accent), var(--np-accent)) 100% 100% / 3px var(--np-b3) no-repeat;
    animation: np-b1 .8s ease-in-out infinite, np-b2 .65s ease-in-out infinite, np-b3 1s ease-in-out infinite;
}

#chat .mes .mesAvatarWrapper {
    position: static;
}

#chat .mes .avatar {
    width: 44px;
    height: 44px;
    margin-right: 14px;
}

body #chat .mes .avatar img {
    width: 44px;
    height: 44px;
    border-radius: 4px !important;
    object-fit: cover;
    object-position: 50% 18%;
}

#chat .mes .ch_name .name_text {
    font-size: 16px;
    font-weight: 700;
    color: var(--np-text);
    transition: color .3s;
}

#chat .mes.last_mes[is_user="false"] .ch_name .name_text {
    color: var(--np-accent);
}

#chat .mes .timestamp {
    color: var(--np-sub);
    font-size: 13px;
    opacity: 1;
}

/* 消息按钮：悬停那一行才出现 */
#chat .mes .mes_button {
    opacity: .75;
    color: var(--np-sub);
}

#chat .mes .mes_button:hover {
    opacity: 1;
    color: var(--np-text);
}

@media (hover: hover) {
    #chat .mes .mes_buttons {
        opacity: 0;
        transition: opacity .15s;
    }

    #chat .mes:hover .mes_buttons,
    #chat .mes:focus-within .mes_buttons {
        opacity: 1;
    }
}

/* 正文 */
#chat .mes_text {
    font-size: var(--np-prose-size);
    line-height: var(--np-prose-leading);
    font-weight: 400;
    color: var(--np-text);
    padding-right: 8px;
}

/* 对白比正文亮一级、稍粗；心理是灰的；代码是深一级的底 */
#chat .mes_text q {
    color: var(--SmartThemeQuoteColor);
    font-weight: 500;
}

#chat .mes_text em,
#chat .mes_text i {
    color: var(--SmartThemeEmColor);
}

#chat .mes_text code {
    background: var(--np-elev);
    color: var(--np-text);
    border-radius: 4px;
    padding: .1em .35em;
    border: 0;
}

#chat .mes_text pre {
    background: var(--np-elev);
    border-radius: 8px;
    border: 0;
}

#chat .mes_text pre code {
    background: none;
    padding: 1em 1.2em;
    line-height: 1.6;
    font-size: 14px;
}

#chat .mes_text blockquote {
    border-left: 3px solid var(--np-accent);
    background: var(--np-hover);
    border-radius: 0 6px 6px 0;
}

/* 主题脚本把左右换版搬到了播放条上，消息里的就不画了 */
html.np-js #chat .mes .swipe_left,
html.np-js #chat .mes .swipe_right,
html.np-js #chat .mes .swipes-counter {
    display: none !important;
}

/* ---------------- 播放条 ---------------- */
#form_sheld {
    position: relative;
}

#send_form {
    background: transparent;
    border: 0;
    border-radius: 0;
    backdrop-filter: none;
}

#nonQRFormItems {
    align-items: center;
    column-gap: 10px;
}

#leftSendForm {
    order: 1;
}

#send_textarea {
    order: 2;
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 22px;
    padding: 11px 18px;
    min-height: 44px;
    font-size: 15px;
    color: var(--np-text);
    transition: background-color .2s, border-color .2s;
}

#send_textarea:hover {
    background: var(--np-elev-hi);
}

/* 酒馆一打开就把光标放进输入框，所以焦点框只淡淡一圈 */
#send_textarea:focus-visible {
    border-color: color-mix(in srgb, var(--np-text) 22%, transparent);
    outline: none;
}

#send_form:has(#send_textarea:focus-visible) {
    border: 0;
    outline: none;
}

#rightSendForm {
    order: 3;
    flex-wrap: nowrap;
    align-items: center;
    gap: 4px;
}

#leftSendForm > div,
#rightSendForm > div {
    color: var(--np-sub);
    opacity: 1;
    transition: color .15s, transform .15s var(--np-ease);
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--np-text);
}

#leftSendForm > div:active,
#rightSendForm > div:active {
    transform: scale(.9);
}

/* 控制钮的顺序：重新生成 · 上一版 · 发送 · 下一版 · 继续 · 代写 */
#np_regen { order: 1; }
#np_prev { order: 2; }
#rightSendForm > #send_but,
#rightSendForm > #mes_stop { order: 3; }
#np_next { order: 4; }
#mes_continue { order: 5; }
#mes_impersonate { order: 6; }
#rightSendForm > div:not(.np-ctl, #send_but, #mes_stop, #mes_continue, #mes_impersonate) { order: 7; }

.np-ctl {
    width: 32px;
    height: 32px;
    display: grid;
    place-items: center;
    font-size: 16px;
    cursor: pointer;
}

.np-ctl.np-off {
    opacity: .35 !important;
    pointer-events: none;
}

/* 发送 = 白色圆形的播放钮；生成中变成暂停（停止） */
#rightSendForm > #send_but,
#rightSendForm > #mes_stop {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    align-items: center;
    justify-content: center;
    background: var(--np-text);
    color: var(--np-base);
    font-size: 16px;
    margin: 0 6px;
}

#rightSendForm > #send_but:hover,
#rightSendForm > #mes_stop:hover {
    color: var(--np-base);
    transform: scale(1.06);
}

#rightSendForm > #send_but:active,
#rightSendForm > #mes_stop:active {
    transform: scale(.94);
}

#send_but::before {
    content: '\f04b';
    margin-left: 2px;
}

/* 停止钮里酒馆自己的图标不要，换成暂停 */
#mes_stop > * {
    display: none !important;
}

#mes_stop::before {
    content: '\f04c';
    font: var(--fa-font-solid);
}

/* 播放条顶边一条进度线；生成中有一段亮光来回走 */
@keyframes np-sweep {
    from { background-position: -40% 0; }
    to { background-position: 140% 0; }
}

#form_sheld::before {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    height: 2px;
    background: var(--np-line);
}

body[data-generating="true"] #form_sheld::before {
    background:
        linear-gradient(90deg, transparent, var(--np-accent), transparent) -40% 0 / 40% 100% no-repeat,
        var(--np-line);
    animation: np-sweep 1.4s linear infinite;
}

/* 播放条左边：正在播放的角色 */
#np_now {
    order: 0;
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    white-space: normal;
}

#np_now img {
    width: 56px;
    height: 56px;
    border-radius: 4px;
    object-fit: cover;
    object-position: 50% 18%;
    flex-shrink: 0;
    background: var(--np-elev);
}

#np_now .np-n {
    font-size: 14px;
    font-weight: 600;
    color: var(--np-text);
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#np_now .np-s {
    font-size: 12px;
    color: var(--np-sub);
    line-height: 1.4;
    white-space: nowrap;
}

/* ==== themes/nowplaying/layout.css ==== */
/* ================================================================
 * 版面：酒馆的左右面板、电脑、手机
 * ================================================================ */

/* ---------------- 酒馆的左右面板 ---------------- */
#left-nav-panel,
#right-nav-panel {
    background: var(--np-panel);
    border: 0;
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* 通用的按钮、输入框：播放器式的胶囊和深一级的底 */
.menu_button {
    background: var(--np-elev);
    border: 0;
    border-radius: 999px;
    color: var(--np-text);
    opacity: 1;
    transition: background-color .15s, transform .15s var(--np-ease);
}

.menu_button:hover {
    background: var(--np-elev-hi);
}

.menu_button:active {
    transform: scale(.96);
}

.text_pole,
select.text_pole {
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 6px;
    color: var(--np-text);
}

.text_pole:focus-visible {
    border-color: color-mix(in srgb, var(--np-text) 50%, transparent);
    outline: none;
}

/* 面板标题（右边是当前角色名） */
#rm_button_selected_ch h2 {
    font: 800 18px/1.3 var(--np-font);
    color: var(--np-text);
    letter-spacing: -.01em;
}

/* 资料库：角色列表一行一行，方形小封面 + 名字 + 一行灰字 */
#rm_print_characters_block .entity_block {
    padding: 8px;
    border-radius: 6px;
    align-items: center;
    gap: 12px;
    transition: background-color .15s;
}

#rm_print_characters_block .entity_block:hover {
    background: var(--np-hover);
}

#rm_print_characters_block .entity_block.np-cur {
    background: var(--np-elev);
}

body #rm_print_characters_block .avatar,
body #rm_print_characters_block .avatar img {
    width: 48px;
    height: 48px;
    border-radius: 4px !important;
    object-fit: cover;
    object-position: 50% 18%;
}

#rm_print_characters_block .ch_name {
    font-size: 15px;
    font-weight: 500;
    color: var(--np-text);
}

#rm_print_characters_block .np-cur .ch_name {
    color: var(--np-accent);
}

#rm_print_characters_block .ch_description {
    color: var(--np-sub);
    font-size: 13px;
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

/* 收藏的角色：酒馆默认金框金字，换成名字后一颗绿星（像「已加入喜欢」） */
body #rm_print_characters_block .is_fav .avatar {
    outline: none;
}

#rm_print_characters_block .is_fav .ch_name {
    color: var(--np-text);
}

#rm_print_characters_block .is_fav .ch_name::after {
    content: ' 005';
    font: var(--fa-font-solid);
    font-size: 10px;
    color: var(--np-accent);
    margin-left: 6px;
    vertical-align: 2px;
}

#rm_print_characters_block .np-cur.is_fav .ch_name,
#rm_print_characters_block .np-cur .ch_name {
    color: var(--np-accent);
}

/* 关掉的世界书 / 预设条目：像播放列表里「暂不可播」的歌——整行变灰字，但不糊，标题照样读得清 */
.world_entry.disabledWIEntry {
    opacity: 1;
    filter: none;
}

.world_entry.disabledWIEntry .text_pole,
.world_entry.disabledWIEntry .world_entry_form_control,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--np-sub);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border-color: transparent;
}

/* 开着的条目：开关是绿的（像播放器的随机播放 / 循环键亮起） */
.world_entry .killSwitch.fa-toggle-on,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--np-accent);
    opacity: 1;
}

/* 滑块：细灰轨 + 白圆点，悬停时圆点变绿 */
body input[type="range"] {
    height: 4px;
    background: color-mix(in srgb, var(--np-text) 28%, transparent);
}

body input[type="range"]:hover {
    filter: none;
}

body input[type="range"]::-webkit-slider-thumb {
    width: 12px;
    height: 12px;
    border: 0;
    background: var(--np-text);
    box-shadow: 0 2px 4px rgba(0, 0, 0, .5);
    transition: transform .15s var(--np-ease), background-color .15s;
}

body input[type="range"]:hover::-webkit-slider-thumb,
body input[type="range"]:focus-visible::-webkit-slider-thumb {
    background: var(--np-accent);
    transform: scale(1.2);
}

body input[type="range"]::-moz-range-thumb {
    width: 12px;
    height: 12px;
    border: 0;
    background: var(--np-text);
}

#rm_print_characters_block .ch_fav_icon {
    color: var(--np-accent);
}

/* 正在播放：打开一个角色时，顶上铺封面色，头像放大成方形封面，名字压在下面 */
#rm_ch_create_block {
    background: linear-gradient(to bottom, var(--np-art), color-mix(in srgb, var(--np-art) 25%, var(--np-panel)) 360px, var(--np-panel) 520px);
    border-radius: 8px;
    padding: 16px;
}

#avatar-and-name-block {
    display: flex;
    flex-direction: column-reverse;
    flex-wrap: nowrap;
    gap: 12px;
}

#avatar_div {
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
}

body #rm_ch_create_block #avatar_div_div.avatar {
    width: 100%;
    height: auto;
    max-width: 420px;
    aspect-ratio: 1;
    border-radius: 8px !important;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(0, 0, 0, .45);
    flex: none;
}

body #rm_ch_create_block #avatar_load_preview {
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 8px !important;
}

#character_name_pole {
    font: 800 26px/1.2 var(--np-font);
    letter-spacing: -.01em;
    background: transparent;
    border-color: transparent;
    padding: 2px 0;
    color: var(--np-on-art);
}

#character_name_pole:hover,
#character_name_pole:focus-visible {
    background: rgba(0, 0, 0, .25);
    padding-inline: 6px;
}

/* 封面下面：名字（主题脚本写进 --np-name；酒馆编辑已有角色时把名字框藏起来了）+ 一排按钮 */
#avatar-and-name-block,
#avatar-and-name-block > .expander,
#avatar-and-name-block > .expander > #avatar_div {
    flex: none;
}

#avatar-and-name-block,
#avatar_controls {
    height: auto !important;
}

#avatar_controls {
    flex: none;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
}

#avatar_controls::before {
    content: var(--np-name, '');
    font: 800 26px/1.2 var(--np-font);
    letter-spacing: -.01em;
    color: var(--np-on-art);
    overflow-wrap: anywhere;
}

/* 「更多…」下拉（改名、导入设定等）：留着，收成一颗小胶囊 */
#avatar_controls > label.flex1 {
    flex: none;
    height: auto;
}

#avatar_controls #char-management-dropdown {
    width: auto;
    margin: 0;
    border-radius: 500px;
    padding-inline: 14px 28px;
    background-color: rgba(0, 0, 0, .3);
}

#avatar_controls .form_create_bottom_buttons_block {
    height: auto;
    flex-wrap: wrap;
    align-content: flex-start;
    justify-content: flex-start;
    gap: 2px;
}

/* 面板顶上的收藏角色快捷头像：小方块 */
#HotSwapWrapper .hotswap .avatar,
#HotSwapWrapper .hotswap .avatar img {
    width: 40px;
    height: 40px;
    border-radius: 4px;
    object-fit: cover;
}

/* 头像下面那排按钮：圆的、透明底，像播放器的「收藏 / 下载 / ⋯」 */
#avatar_controls .menu_button {
    background: transparent;
    color: color-mix(in srgb, var(--np-on-art) 75%, transparent);
    width: 36px;
    height: 36px;
    padding: 0;
    display: grid;
    place-items: center;
    font-size: 17px;
}

#avatar_controls .menu_button:hover {
    color: var(--np-on-art);
    background: rgba(255, 255, 255, .08);
}

/* 下面一段一段的设定 */
#rm_ch_create_block textarea {
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 8px;
    color: var(--np-text);
    line-height: 1.6;
}

/* ================================================================
 * 电脑
 * ================================================================ */
@media screen and (min-width: 1001px) {
    #top-bar {
        width: 100vw;
    }

    #sheld {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
    }

    #chat {
        max-height: none;
    }

    #form_sheld {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        width: auto;
        margin: 0;
        padding: 12px 16px;
        background: var(--np-base);
        z-index: 40;
    }

    #form_sheld::before {
        left: calc((100vw - var(--sheldWidth)) / 2);
        right: calc((100vw - var(--sheldWidth)) / 2);
        top: 2px;
        border-radius: 2px;
    }

    #np_now {
        width: max(240px, calc((100vw - var(--sheldWidth)) / 2 - 16px));
    }

    /* 酒馆的左右面板：留缝、圆角，底下给播放条让位 */
    .fillLeft,
    .fillRight {
        top: var(--topBarBlockSize);
        width: calc((100vw - var(--sheldWidth)) / 2 - 2 * var(--np-gap));
        border-radius: 8px;
    }

    .fillLeft {
        left: var(--np-gap);
    }

    .fillRight {
        right: var(--np-gap);
        left: auto;
    }

    .fillLeft.openDrawer,
    .fillRight.openDrawer {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
    }
}

/* ================================================================
 * 手机：顶栏挪到底部当标签栏（图标 + 两个字），封面色一直铺到屏幕顶
 * ================================================================ */
@media screen and (max-width: 1000px) {
    html:root {
        --topBarBlockSize: env(safe-area-inset-top, 0px);
        --np-tab: calc(54px + env(safe-area-inset-bottom, 0px));
    }

    #ai-config-button { --np-label: '预设'; }
    #sys-settings-button { --np-label: '连接'; }
    #advanced-formatting-button { --np-label: '格式'; }
    #WI-SP-button { --np-label: '世界书'; }
    #user-settings-button { --np-label: '设置'; }
    #backgrounds-button { --np-label: '背景'; }
    #extensions-settings-button { --np-label: '扩展'; }
    #persona-management-button { --np-label: '人设'; }
    #rightNavHolder { --np-label: '角色'; }

    /* 酒馆给 <html> 加了 translateZ(0)，fixed 的 bottom: 0 会对不上屏幕底，所以从顶上量 */
    #top-bar {
        top: calc(100dvh - var(--np-tab)) !important;
        bottom: auto;
        height: var(--np-tab);
        background: var(--np-base);
    }

    #top-settings-holder {
        position: fixed;
        top: calc(100dvh - var(--np-tab)) !important;
        bottom: auto;
        left: 0;
        width: 100vw;
        height: var(--np-tab);
        padding: 0 4px env(safe-area-inset-bottom, 0px);
        box-sizing: border-box;
        align-items: stretch;
    }

    #top-settings-holder > .drawer {
        flex: 1 1 0;
        min-width: 0;
    }

    #top-settings-holder .drawer-toggle {
        width: 100%;
        height: 100%;
        display: flex;
        align-items: stretch;
    }

    #top-settings-holder .drawer-icon {
        width: 100%;
        height: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 4px;
    }

    #top-settings-holder .drawer-icon::before {
        width: 22px;
        height: 22px;
    }

    /* 小点换成两个字的标签 */
    #top-settings-holder .drawer-icon::after {
        content: var(--np-label, '');
        position: static;
        width: auto;
        height: auto;
        margin: 0;
        background: none;
        border-radius: 0;
        transform: none;
        font: 500 10px/1 var(--np-font);
        white-space: nowrap;
    }

    #top-settings-holder .drawer-icon:active {
        transform: scale(.9);
    }

    /* 聊天区和各个面板：从屏幕顶到标签栏 */
    html body #sheld {
        top: var(--topBarBlockSize) !important;
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
        border-radius: 0;
    }

    .drawer-content {
        top: var(--topBarBlockSize) !important;
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
        border: 0;
    }

    #left-nav-panel.openDrawer,
    #right-nav-panel.openDrawer {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
    }

    #rm_ch_create_block {
        border-radius: 0;
    }

    #chat {
        max-height: none;
        min-height: 0;
        padding: 0 var(--np-m-pad) 12px;
    }

    /* 专辑头：封面居中，名字靠左、不加小标签，绿钮在右边 */
    #np_hero {
        flex-direction: column;
        align-items: stretch;
        gap: 18px;
        padding: 28px 0 4px;
    }

    #np_hero .np-cover {
        width: 64%;
        max-width: 260px;
        align-self: center;
    }

    #np_hero .np-kicker {
        display: none;
    }

    #np_hero .np-title {
        font-size: 24px;
        font-weight: 800;
        letter-spacing: -.01em;
        margin: 0 0 6px;
    }

    #np_hero .np-meta {
        font-size: 13px;
    }

    #np_actions {
        align-self: stretch;
        padding: 4px 0 12px;
        gap: 12px;
    }

    #np_actions .np-hint {
        order: 1;
        font-size: 13px;
    }

    #np_actions .np-play {
        order: 2;
        margin-left: auto;
        width: 48px;
        height: 48px;
        font-size: 18px;
    }

    #np_top {
        padding: 0 var(--np-m-pad);
        font-size: 16px;
        height: 52px;
    }

    #np_top .np-play {
        width: 32px;
        height: 32px;
        font-size: 12px;
    }

    /* 消息：更紧凑 */
    #chat .mes {
        padding: 10px 4px 12px;
    }

    #chat .mes::before {
        content: none;
    }

    #chat .mes .avatar,
    body #chat .mes .avatar img {
        width: 34px;
        height: 34px;
    }

    #chat .mes .avatar {
        margin-right: 12px;
    }

    #chat .mes .ch_name .name_text {
        font-size: 14px;
    }

    #chat .mes .timestamp {
        font-size: 12px;
    }

    #chat .mes_text {
        font-size: calc(var(--np-prose-size) - 1px);
        line-height: 1.7;
    }

    #chat .mes .mes_button {
        font-size: 14px;
        opacity: .55;
    }

    /* 生成中：音柱挪到名字前面 */
    body[data-generating="true"] #chat .mes.last_mes[is_user="false"]::before {
        content: '';
        left: 50px;
        top: 13px;
        width: 12px;
        height: 12px;
    }

    body[data-generating="true"] #chat .mes.last_mes[is_user="false"] .ch_name .name_text {
        padding-left: 18px;
    }

    /* 迷你播放条：封面 · 输入框 · 菜单 · 扩展 · 发送 */
    #form_sheld {
        flex-shrink: 0;
        margin: 0 8px 8px;
        width: auto;
        border-radius: 8px;
        background: color-mix(in srgb, var(--np-art) 58%, #000);
        overflow: hidden;
        padding: 6px 8px 8px 6px;
    }

    #form_sheld::before {
        top: auto;
        bottom: 0;
        left: 8px;
        right: 8px;
        background: rgba(255, 255, 255, .22);
    }

    #nonQRFormItems {
        column-gap: 6px;
    }

    #np_now {
        width: auto;
    }

    #np_now img {
        width: 36px;
        height: 36px;
    }

    #np_now > div {
        display: none;
    }

    #send_textarea {
        background: transparent;
        border-color: transparent;
        color: var(--np-on-art);
        padding: 8px 4px;
        min-height: 36px;
        font-size: 15px;
        text-align: left;
        resize: none;
    }

    #send_textarea::placeholder {
        color: rgba(255, 255, 255, .7);
    }

    #send_textarea:hover,
    #send_textarea:focus-visible {
        background: transparent;
        border-color: transparent;
    }

    #leftSendForm {
        order: 3;
        width: auto;
        gap: 2px;
    }

    #rightSendForm {
        order: 4;
        width: auto;
    }

    #leftSendForm > div,
    #rightSendForm > div {
        color: rgba(255, 255, 255, .82);
    }

    #np_prev,
    #np_next,
    #np_regen,
    #mes_impersonate,
    #mes_continue {
        display: none !important;
    }

    #rightSendForm > #send_but,
    #rightSendForm > #mes_stop {
        width: 34px;
        height: 34px;
        margin: 0 0 0 4px;
        font-size: 13px;
        background: #fff;
        color: #000;
    }
}
/* ==== end themes/nowplaying/layout.css ==== */
